-- Table: users (81 rows)
SELECT setval('users_id_seq', COALESCE((SELECT MAX(id) FROM users), 1));

-- Table: supplies (133 rows)
SELECT setval('supplies_id_seq', COALESCE((SELECT MAX(id) FROM supplies), 1));

-- Table: system_settings (9 rows)
SELECT setval('system_settings_id_seq', COALESCE((SELECT MAX(id) FROM system_settings), 1));

-- Table: procurements (2 rows)
SELECT setval('procurements_id_seq', COALESCE((SELECT MAX(id) FROM procurements), 1));

-- Table: procurement_items (266 rows)
SELECT setval('procurement_items_id_seq', COALESCE((SELECT MAX(id) FROM procurement_items), 1));

